WITH cfg AS MATERIALIZED (
 SELECT capacidad_total FROM public.parqueadero_configuracion WHERE id=1 FOR UPDATE
), auth AS MATERIALIZED (
 SELECT pa.id,pa.parqueadero_usuario_id,pm.tipo_vehiculo tipo_autorizado FROM public.parqueadero_autorizaciones pa JOIN public.parqueadero_usuarios pu ON pu.id=pa.parqueadero_usuario_id JOIN public.parqueadero_pagos pp ON pp.id=pa.pago_id JOIN public.parqueadero_modalidades pm ON pm.id=pp.modalidad_id WHERE pa.id=$1::bigint AND pa.estado='VIGENTE' AND pp.estado='APROBADO' AND pu.estado='ACTIVO' AND CURRENT_DATE BETWEEN pa.fecha_inicio AND pa.fecha_fin
), habitual AS MATERIALIZED (
 SELECT a.*,v.id vehiculo_id,v.placa FROM auth a LEFT JOIN LATERAL (SELECT id,placa FROM public.parqueadero_vehiculos WHERE parqueadero_usuario_id=a.parqueadero_usuario_id AND activo=TRUE ORDER BY es_principal DESC,id LIMIT 1) v ON TRUE
), latest AS MATERIALIZED (
 SELECT DISTINCT ON(parqueadero_usuario_id) parqueadero_usuario_id,tipo_movimiento,UPPER(COALESCE(placa_observada,'')) placa_observada FROM public.parqueadero_accesos WHERE estado_validacion='AUTORIZADO' ORDER BY parqueadero_usuario_id,fecha_hora DESC,id DESC
), occupancy AS MATERIALIZED (SELECT count(*)::int total FROM latest WHERE tipo_movimiento='ENTRADA'), eligible AS MATERIALIZED (
 SELECT h.* FROM habitual h CROSS JOIN cfg CROSS JOIN occupancy o WHERE h.vehiculo_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM latest l WHERE l.parqueadero_usuario_id=h.parqueadero_usuario_id AND l.tipo_movimiento='ENTRADA') AND o.total<cfg.capacidad_total AND (NOT $3::boolean OR $5=h.tipo_autorizado) AND (NOT $3::boolean OR NOT EXISTS(SELECT 1 FROM public.parqueadero_vehiculos pv WHERE UPPER(pv.placa)=UPPER($4))) AND (NOT $3::boolean OR NOT EXISTS(SELECT 1 FROM latest l WHERE l.tipo_movimiento='ENTRADA' AND l.placa_observada=UPPER($4)))
), inserted_temp AS (
 INSERT INTO public.parqueadero_vehiculos_temporales(parqueadero_usuario_id,autorizacion_id,vehiculo_habitual_id,placa_temporal,tipo_vehiculo,fecha_inicio,fecha_fin,registrado_por) SELECT parqueadero_usuario_id,id,vehiculo_id,UPPER($4),$5,CURRENT_DATE,CURRENT_DATE,$2::bigint FROM eligible WHERE $3::boolean RETURNING id,parqueadero_usuario_id,autorizacion_id,placa_temporal
), inserted_temp_access AS (
 INSERT INTO public.parqueadero_accesos(parqueadero_usuario_id,autorizacion_id,vehiculo_id,vehiculo_temporal_id,placa_observada,tipo_movimiento,estado_validacion,usuario_control_id) SELECT parqueadero_usuario_id,autorizacion_id,NULL,id,UPPER(placa_temporal),'ENTRADA','AUTORIZADO',$2::bigint FROM inserted_temp RETURNING id,vehiculo_temporal_id,placa_observada
), inserted_regular_access AS (
 INSERT INTO public.parqueadero_accesos(parqueadero_usuario_id,autorizacion_id,vehiculo_id,vehiculo_temporal_id,placa_observada,tipo_movimiento,estado_validacion,usuario_control_id) SELECT parqueadero_usuario_id,id,vehiculo_id,NULL,UPPER(placa),'ENTRADA','AUTORIZADO',$2::bigint FROM eligible WHERE NOT $3::boolean RETURNING id,vehiculo_temporal_id,placa_observada
), inserted_access AS (SELECT * FROM inserted_temp_access UNION ALL SELECT * FROM inserted_regular_access)
SELECT EXISTS(SELECT 1 FROM inserted_access) success,(SELECT id::int FROM inserted_access LIMIT 1) id,(SELECT vehiculo_temporal_id::int FROM inserted_access LIMIT 1) "temporaryVehicleId",(SELECT placa_observada FROM inserted_access LIMIT 1) plate,CASE WHEN NOT EXISTS(SELECT 1 FROM cfg) THEN 'Configure la capacidad del parqueadero.' WHEN NOT EXISTS(SELECT 1 FROM auth) THEN 'El ticket no está vigente o el usuario está inactivo.' WHEN NOT EXISTS(SELECT 1 FROM habitual WHERE vehiculo_id IS NOT NULL) THEN 'El usuario no tiene un vehículo habitual activo.' WHEN EXISTS(SELECT 1 FROM habitual h JOIN latest l ON l.parqueadero_usuario_id=h.parqueadero_usuario_id WHERE l.tipo_movimiento='ENTRADA') THEN 'El usuario ya tiene un vehículo dentro del parqueadero.' WHEN (SELECT total FROM occupancy)>=(SELECT capacidad_total FROM cfg) THEN 'No hay espacios disponibles.' WHEN $3::boolean AND $5<>(SELECT tipo_autorizado FROM auth) THEN 'El vehículo temporal debe ser del tipo cubierto por el ticket.' WHEN $3::boolean AND EXISTS(SELECT 1 FROM public.parqueadero_vehiculos WHERE UPPER(placa)=UPPER($4)) THEN 'La placa indicada ya está registrada como vehículo habitual.' WHEN $3::boolean AND EXISTS(SELECT 1 FROM latest WHERE tipo_movimiento='ENTRADA' AND placa_observada=UPPER($4)) THEN 'La placa temporal ya se encuentra dentro del parqueadero.' ELSE 'No fue posible registrar la entrada.' END error,CASE WHEN EXISTS(SELECT 1 FROM inserted_access) THEN 201 ELSE 409 END "statusCode";
